t_lo = max(2, n // 2 + 1)
t_hi = n - 1
if t_lo > t_hi:
    t_lo = 2
    t_hi = n - 1
target = rng.randint(t_lo, t_hi)

# Package assignment
assign = {
    'deck_size': n,
    'skip_pattern_csv': ','.join(map(str, pattern)),
    'target_label': target
}
return assign

